******************************************************************* ADB main** Copyright (c) Apple Computer, Inc. 1986-1988* All Rights Reseverd** Change History** 03 Nov 88	Steven Glass & Joe Bo** Made STool public so could call from another bank.******************************************************************	STRING ASIS	BLANKS OFF	TITLE 'ADB Tool Sets'** The following is the SKI tool code.* It implements calls to the Single-Chip-Microcontroller (uC) using* the SKI protocol.* For more information see the Single-Chip-Microcontroller (uC) ERS &* the SKI TOOL ERS** The following Flags/Variables are used:** STATUSTMP: Used to save pending status data from uC. When	a* command is being sent interrupts are locked out, but* the uC status has	to be read. It is acted on at the* end of the routine.(Status = Abort,Flush,Desktop,etc.)** PENDFLG: Indicates if a command is pending. If a command is* clr=nope Pending then it should be finished before any other* set=pend command can be initiated. If	a pending command is* requested while this flag is set then	the code* returns w/ an error code indicating busy - try again* later. If an immediate command is requested then* the pending command is completed and a flag is set:** RSPNSFLG: Indicates if a pending command was completed during* clr=none a request for an immediate command. The response	from* set=pend the pending command is processed after the immediate* command is done.** RSPNSBUF: Buffer to hold response: 8 bytes for data, 1 for count** The code makes extensive use of the stack and direct page. At* the beginning of most tool functions room is made on the* stack and then the direct page is placed on top of the stack to* allow easy access	to these variables.	In most tool functions the* stack looks like this:** 26-27 Word - Input Parameter* 22-25 Long - Input Parameter* 20-21 Word - Input Parameter* 1D-1F Adrs - Tool	Dispatcher Return address* 1A-1C Adrs - Calling Code Return Address* 18-19 Word - Original Direct Page* 17 Byte - Original Processor Status* 16 Byte - Original Data Bank* 14-15 Word - Variable* A-13 10 - Response Buffer 2* 0-09 10 - Response Buffer 1**	include '::sys.equs.asm';-------------------------------------------;; Equates form procedure ADBEQUS;;-------------------------------------------FDBVERSION	EQU $0300	;VERSION #MYTOOLNUM	EQU $09TRUE	EQU $FFFFCMDFULL	EQU $01	;COMMAND REG FULL BIT (IN KEYGLOO STATUS)DATAFULL	EQU $20	;DATA REG FULL BIT (IN KEYGLOO STATUS)STATUSBIT	EQU $80	;UC STATUS - RESPONSE BITABORTBIT	EQU $40	;UC STATUS - ABORT BITDESKBIT	EQU $20	;UC STATUS - DESKTOP MANAGER BITFLUSHBIT	EQU $10	;UC STATUS - FLUSH BITIDREG	EQU $F0	;FDB COMMAND MASK TO READ ID REG.(3)DISSRQ	EQU $70	;FDB COMMAND MASK TO DISABLE SRQENSRQ	EQU $50	;FDB COMMAND MASK TO ENABLE SRQTALKCMD	EQU $C0	;FDB COMMAND MASK FOR TALK POLLJMLOPCODE	EQU $5C	;OPCODE FOR JML al INSTRUCTIONHARDERR	EQU $0010	;CODE FOR HARD ERRORMAXERR	EQU $0081	;CODE FOR SOFT ERRORBUSYERR	EQU $0082	;CODE FOR BUSY ERRORNODEVERR	EQU $0083	;CODE FOR NO DEVICE	PRESENT ERRORFULLERR	EQU $0084	;CODE FOR SRQ LIST FULLDATABNK	EQU $00E1	;*;-------------------------------------------;; Direct Page Addressing Modes;RSPNSBUF	EQU $0	;START AT BOTTOM OF	DIRECT PAGERSPNSLNG	EQU 10	;BUFFER FOR PENDING	COMMAND RESPONSEPARMS	EQU RSPNSLNG*2	;USED DURING ENDCALLPHBOFFSET	EQU PARMS+2PHPOFFSET	EQU PHBOFFSET+1PHDOFFSET	EQU PHPOFFSET+1RTLGLU	EQU PHDOFFSET+2	;GLU ROUTINE RETURN	ADDRESSRTLCALL	EQU RTLGLU+3	;CALLING ROUTINE RETURN ADDRESSZPTOS	EQU RTLCALL+3	;OFFSET INTO STACK FOR 1ST DATA BYTEUCCMD	EQU ZPTOS	;COMMAND TO uCFDBADRS	EQU ZPTOS	;FDB ADDRESSDATAPTR	EQU UCCMD+2	;POINTER TO DATACPLTVCTR	EQU UCCMD+2	;COMPLETION VECTOR ADDRESSHOWMANY	EQU DATAPTR+4	;DATA BYTE COUNTRDMEMPTR	EQU DATAPTR+4	;USED TO GET DATAINPTR FOR RDMEM COMMANDMAXCOUNT	EQU DATAPTR+4	;MAXIMUM BUFFER COUNT-USED IN READBYTESFDBCMD	EQU CPLTVCTR+4	;FDB COMMAND BYTE-2ND SENT DURING FDBRCV*;--------------------------------------------;SCALELNG	EQU $000B	;LENGTH OF ALL SCALING VALUESPENDBIT	EQU $0080	;COMMAND PENDING FLAG BITABSBIT	EQU $0040	;ABSOLUTE DEVICE AUTO-POLLED (16-BIT)RSPNSBIT	EQU $0020	;PENDING COMMAND WAS PROCESSEDSRQMAX	EQU $10	;MAX OF 16 DEVICES (1-16)ERRCODE	EQU $0911	;CODE OF SYSTEM DEATH MESSAGE;--------------------------------------------;CMDREG	EQU $C026*;--------------------------------------------;SCALEDATA	EQU $E103D0YMULTIPLY	EQU SCALEDATA	;AREA IN BANK $E1XMULTIPLY	EQU YMULTIPLY+2YOFFSET	EQU XMULTIPLY+2XOFFSET	EQU YOFFSET+2YDIVIDE	EQU XOFFSET+2XDIVIDE	EQU YDIVIDE+2VCTRCPLT	EQU $E103DC	;COMPLETION VECTOR ADDRESS, 4 BYTESSRQTBL	EQU $E1154A	;A COMPLETION VECTOR FOR EACH DEVICEPENDFLAG	EQU $E10FD6	;3rd DATA BUFFER, BANK $E1RSPNSFLAG	EQU PENDFLAG	;SAME LOCATION, BUT	CLEAR TO UNDERSTANDFLAGS	EQU PENDFLAG	; ";-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY ABSOFF	ENTRY ABSON	ENTRY ACTIVE	ENTRY ALL	ENTRY APDOWN	ENTRY APUP	ENTRY BUSY	ENTRY BYTES	ENTRY CALL	ENTRY CHKDOP	ENTRY CLEAN	ENTRY CLRSRQTBL	ENTRY CMDNP	ENTRY CMDP	ENTRY CMDS	ENTRY DBTOE1	ENTRY DONESRQ	ENTRY DUMMY	ENTRY ERRHARD	ENTRY ERRNODEV	ENTRY ERROR3	ENTRY ERRORCALL	ENTRY ERRORDMEM	ENTRY ERRORSND	ENTRY ERROUT	ENTRY ERRRSPNS	ENTRY ERRSRQ	ENTRY ERRSRQFLL	ENTRY EXECMD	ENTRY FDBRCV	ENTRY FDBTALK	ENTRY FDBTIMEOUT	ENTRY GETPATA	ENTRY GETVERSION	ENTRY GOODRSP	ENTRY GOTRSPNS	ENTRY HARDCALL	ENTRY IMD	ENTRY INITOOL	ENTRY INITSKI	ENTRY INTRSPNS	ENTRY INTSRQ	ENTRY ITPLB	ENTRY NOERR	ENTRY NOMORE	ENTRY NORSPNSE	ENTRY NOSTSP	ENTRY NOTABORT	ENTRY NOTSET	ENTRY NXTDEV	ENTRY OFLIST	ENTRY RCVDATA	ENTRY RCVTOOL	ENTRY RDABS	ENTRY RDMEMTOOL	ENTRY RDSCALE	ENTRY READRSPNS	ENTRY RESETSKI	ENTRY RET1	ENTRY RSTSRQ	ENTRY SAVEWD	ENTRY SCALE	ENTRY SCL	ENTRY SCMD	ENTRY SCMD2	ENTRY SDATA	ENTRY SKIPRMV	ENTRY SNDCMDSTR	ENTRY SRQCPL	ENTRY SRQCPLT	ENTRY SRQNOTFND	ENTRY SRQPL	ENTRY SRQRMV	ENTRY STOOL	ENTRY STRVCTR	ENTRY TBL	ENTRY TONOERR*********************************************************************** FUNCTION TABLE** This code should be at the beginning of the tool set**********************************************************************SKIFNCTBL	PROC EXPORT	ENTRY HereHere		; 	DC.L (The-Here)/4	;num calls +1	ENTRY FUNC1FUNC1	DC.L INITSKI-1	;POWER ON - INIT TOOL SET	ENTRY FUNC2FUNC2	DC.L APUP-1	;APPLICATION START UP INIT	ENTRY FUNC3FUNC3	DC.L APDOWN-1	;APPLICATION SHUT DOWN INIT	ENTRY FUNC4FUNC4	DC.L GETVERSION-1	;VERSION #	ENTRY FUNC5FUNC5	DC.L RESETSKI-1	;RESET	ENTRY FUNC6FUNC6	DC.L ACTIVE-1	;RESERVED	ENTRY FUNC7FUNC7	DC.L DUMMY-1	;RESERVED	ENTRY FUNC8FUNC8	DC.L DUMMY-1	;RESERVED*	ENTRY MYFUNC9MYFUNC9	DC.L STOOL-1	;S	ENTRY MYFUNCAMYFUNCA	DC.L RCVTOOL-1	;RCV	ENTRY MYFUNCBMYFUNCB	DC.L RDMEMTOOL-1	;RDMEM;MYFUNCC DC I4'RESETFDB-1' ;RESET ENTRY	POINT (NOT OFFICIAL	CALL)	ENTRY MYFUNCCMYFUNCC	DC.L DUMMY-1	;RESETFDB NO LONGER	THERE	ENTRY MYFUNCDMYFUNCD	DC.L FDBTALK-1	;FDBTALK	ENTRY MYFUNCEMYFUNCE	DC.L FDBRCV-1	;FDBRCV	ENTRY MYFUNCFMYFUNCF	DC.L ABSON-1	;ABSOLUTE ON	ENTRY MYFUNC10MYFUNC10	DC.L ABSOFF-1	;ABSOLUTE OFF	ENTRY MYFUNC11MYFUNC11	DC.L RDABS-1	;READ ABSOLUTE ON/OFF	ENTRY MYFUNC12MYFUNC12	DC.L SCALE-1	;SET ABSOLUTE SCALE	VALUES	ENTRY MYFUNC13MYFUNC13	DC.L RDSCALE-1	;READ ABSOLUTE SCALE VALUES	ENTRY MYFUNC14MYFUNC14	DC.L SRQPL-1	;ADD DEVICE TO SRQ POLL LIST	ENTRY MYFUNC15MYFUNC15	DC.L SRQRMV-1	;REMOVE DEVICE FROM	SRQ POLL LIST	ENTRY MYFUNC16MYFUNC16	DC.L CLRSRQTBL-1	;CLEAR OUT SRQ TABLE OF ALL ENTRIES	ENTRY TheThe		; 	ENDP;         copy  ADBInit************************************************************************* Init call for tool kit* FLAGS -> clear except for ABSBIT (auto-poll on)* Put JML op code ($5C) into CPLTVCTR* Clear SRQNUM, SRQPTR, SRQMRU, SRQCNT* Load in interrupt	vectors: SRQ, RESPONSE*INITSKI	PROC	LONGA ON	LONGI ON	LONGA ON	LONGI OFF	SEP #$10	PHB	;SAVE DATA BANK	JSR DBTOE1	;Changes data bank register to $E1	LDA #ABSBIT	;SAVE FLAGS (ABSOLUTE ON, OTHERS OFF)	STA |FLAGS	;& ZEROS STATUSTMP IN HI BYTE	STZ |SRQNUM	;ZERO OUT SRQNUM & SRQCNT	STZ |SRQPTR	;ZERO OUT SRQPTR & SRQMRU	LDX #$0A	;CLR OUT 12 SCALING	BYTES	ENTRY CLRABSDATACLRABSDATA	STZ |SCALEDATA,X	;ZERO OUT ABSOLUTE SCALE DATA	DEX	BPL CLRABSDATA* ;USE A,X APPROPRIATELY FOR 8/16 BIT	LDX #JMLOPCODE	;PATCH OPCODE FOR JMP LONG INTO	STX |VCTRCPLT	;HI BYTE OF COMPLETION VECTOR	LDX #^INTSRQ	;PATCH IN SRQ INTERRUPT VECTOR	STX |IRQ_SRQ+3	LDA #INTSRQ	STA |IRQ_SRQ+1	LDX #^INTRSPNS	;PATCH IN RESPONSE INTERRUPT VECTOR	STX |IRQ_RESPONSE+3	LDA #INTRSPNS	STA |IRQ_RESPONSE+1	REP #$10	LONGI ON	BRA ITPLB* Version #*	ENTRY GETVERSIONGETVERSION		;       	LONGA ON	LONGI ON	PHB	;SAVE DATA BANK FOR	SAVEWD	LDA #FDBVERSION	BRA SAVEWD	;PUSH ONTO STACK AND RETURNS*	ENTRY ACTIVEACTIVE		;       	LONGA ON	LONGI ON	PHB	LDA #TRUE	;ALWAYS ACTIVE	BRA SAVEWD;         copy  ADBAbs	ENTRY ABSTOOLABSTOOL	PROC	LONGA ON	LONGI ON*USING ADBEQUS** ABSON/ABSOFF/RDABS* Command to enable/disable automatic polling of an absolute device*	ENTRY ABSONABSON		;       ;USE 16-BIT	MODE ON 8-BIT DATA	LONGA ON	LONGI ON	PHB	JSR DBTOE1	;Changes data bank register to $E1	LDA #ABSBIT	;GET 16-BIT VALUE (HIGH BYTE CLEAR)	TSB |FLAGS	;SET FLAG BIT (FLAG+1 UNDAMAGED)	BRA ITPLB	ENTRY ABSOFFABSOFF		;       ;USE 16-BIT	MODE ON 8-BIT DATA	LONGA ON	LONGI ON	PHB	JSR DBTOE1	;Changes data bank register to $E1	LDA #ABSBIT	;GET 16-BIT VALUE (HIGH BYTE CLEAR)	TRB |FLAGS	;CLEAR FLAG BIT (FLAG+1 UNDAMAGED)	BRA ITPLB	ENTRY RDABSRDABS		;       ;16-BIT MODE INSTRUCTION	LONGA ON	LONGI ON	PHB	JSR DBTOE1	;Changes data bank register to $E1	LDA #$0000	;ABSBIT STORED AS BOOLEAN 1=TRUE,0=FALSE	BIT |FLAGS-1	;FAKE 16-BIT MODE INTO SETTING V FLAG	BVC SAVEWD	; PUTS BOOLEAN 0=FALSE 1=TRUE	INC A	;INVERT TO TRUE	ENTRY SAVEWDSAVEWD		;       	STA $8,S	;PUT BOOLEAN DIRECTLY INTO STACK	ENTRY ITPLBITPLB		;       	PLB* Application Start-up* Application Shut-down*	ENTRY APUPAPUP		;       	ENTRY APDOWNAPDOWN		;       	ENTRY DUMMYDUMMY		;       	ENTRY RESETSKIRESETSKI		;       	ENTRY ITIT		;       	LONGA ON	LONGI ON*	LDA #$0000	CLC	RTL** SCALE/RDSCALE* Routine to set/read the scaling values for absolute devices*	ENTRY RDSCALERDSCALE		;       ;ENTRY POINT FOR READING SCALE VALUES	LONGA ON	LONGI ON	PHD	PHP	PHB	JSR INITOOL	LONGA OFF	LONGI ON	TCS*	LDY #SCALELNG	;LENGTH OF SCALING VALUES	ENTRY GETSCALEGETSCALE	LDA |SCALEDATA,Y	;GET SCALE VALUE	STA [<ZPTOS],Y	DEY	BPL GETSCALE*	BRA SCL	ENTRY SCALESCALE		;       ;ENTRY POINT FOR SETTING SCALE VALUES	LONGA ON	LONGI ON	PHD	PHP	PHB	JSR INITOOL	LONGA OFF	LONGI ON	TCS*	LDY #SCALELNG	;LENGTH OF SCALING VALUES	ENTRY STRSCALESTRSCALE	LDA [<ZPTOS],Y	;GET SCALE VALUE	STA |SCALEDATA,Y	;AND SAVE IT	DEY	BPL STRSCALE*	ENTRY SCLSCL	LDX #4	;CLEAN UP 4 BYTES	JMP NOERR	;;         copy  ADBSrq* uC TOOL SET - SRQ	COMMANDS.** SRQPL* Installs new device into SRQ TABLE to	be polled when an SRQ occurs* on FDB. If data is received from that	device then it is passed to* completion vector	and the device is put in SRQMRU.* Routine starts by	verifying that a device exists at* address designated. It does this by sing the FDB talk command* to the ID register (3) and getting a response. If a command* is already pending then it reads it before starting ID. Since* the ID command also reads a response it must not clobber the* data stored in response buffer (ignores ID data instead).* After routine has	determined that device exists at specified* address adds one more device to SRQNUM and SRQ TABLE if there* is room for one more.* Finally the devices completion vector	is stored at the  of* the SRQTBL, along	with the FDB address/register.** Variables:* SRQTBL = Table of	SRQ devices - each device requires 4 bytes* Byte 0 -> FDB Address & Register* Bytes 1-3 -> Completion Vector Address (1=low, 3=bank)* SRQMAX = Maximum number of entries allowed in SRQ table* SRQNUM = Number of devices currently installed in SRQ table* SRQPTR = Pointer to next device in SRQ table to be polled(1..SRQNUM)* SRQMRU = Most recent device in table to return data* SRQCNT = Count of	number of devices polled since data was	received* from most recently used device - SRQMRU (SRQNUM..1).**	ENTRY ADBSRQSTADBSRQST	PROC	LONGA ON	LONGI ON*USING ADBEQUS*	ENTRY SRQPLSRQPL		;       	LONGA ON	LONGI ON	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	JSR INITOOL	;DO INIT STUFF	LONGA OFF	LONGI ON	TCS	;OPENS UP BUFFER INSIDE STACK*	LDA <CPLTVCTR+3	;MAKE SURE HI BYTE OF VECTOR=0	BNE ERRSRQ	;NOT =0 THEN FLAG ERROR*	JSR CHKDOP	;IF PING FLAG SET THEN READ RESPONSE	BCS ERRSRQ	;ERROR ENCOUNTERED*	LDA <FDBADRS	;GET FDB ADDRESS	AND #$0F	;MASK OFF EVERYTHING ELSE	ORA #IDREG	;APP FDB ID REG.	JSR SDATA	;S COMMAND	BCS ERRSRQ*	LONGA ON	REP #$20	;16-BIT	TDC	;MAKE ROOM FOR RESPONSE BY MOVING	ADC #$000A	;DIRECT PAGE - CARRY CLEAR FROM ABOVE	TCD	;RESPONSE PUT IN BOTTOM (0-9) DIRECT PG	LONGA OFF	SEP #$20*	JSR READRSPNS	;GET ID RESPONSE	PHP	;SAVE CARRY*	LONGA ON	REP #$20	;16-BIT M	TDC	;MAKE ROOM FOR RESPONSE BY MOVING	SBC #$0009	;DIRECT PAGE - CARRY CLEAR FROM ABOVE	TCD	;RESPONSE PUT IN BOTTOM (0-9) DIRECT PG	LONGA OFF	SEP #$20	;8-BIT M*	PLP	;GET CARRY	BCS ERRSRQ	;CHK IF ERROR ENCOUNTERED ON RESPONSE	LDA <RSPNSBUF+RSPNSLNG ;CHECK IF ID EXISTS	BEQ ERRNODEV	;NO DEVICE AT SPECIFIED ADDRESS*	LDA |SRQNUM	;GET SRQ NUMBER	CMP #SRQMAX	;AND CHECK IF MAX	BCS ERRSRQFLL	;SRQ LIST FULL	TAY	;SAVE OFF SRQ INDEX	ASL A	;GET INDEX INTO SRQTBL BY MULTPLYING	ASL A	;BY 4	XBA	LDA #0	;CLEAR OUT HI BYTE	XBA	TAX	INY	;MOVE INDEX	TYA	;AND SAVE IN INDEX POINTER	STA |SRQCNT	;RESTORE COUNT	STA |SRQNUM	;STILL ROOM SO ADD 1 MORE	LDA <FDBADRS	;MOVE FDB ADDRESS/REGISTER	STA |SRQTBL,X	; INTO SRQTBL (8-BIT)	LDA <CPLTVCTR	;MOVE HI ADRS OF COMPLETION VECTOR	STA |SRQTBL+1,X	;INTO TABLE	LDA <CPLTVCTR+1	;	STA |SRQTBL+2,X	LDA <CPLTVCTR+2	;MOVE BANK OF COMPLETION VECTOR	STA |SRQTBL+3,X	STZ |SRQPTR	;RESET POINTER TO BEGIN	STZ |SRQMRU	;RESET MRU TO ZERO*	JSR IMD	;PROCESS ANY PING STATUS	LDX #$0006	;CLEAN 6 BYTES OFF STACK	JMP NOERR	;AND NO ERROR	ENTRY ERRNODEVERRNODEV	JSR IMD	;PROCESS ANY PING STATUS	LDY #NODEVERR	;FLAG NO DEVICE ERROR	BRA ERRHARD	ENTRY ERRSRQFLLERRSRQFLL	JSR IMD	;FLAG FULL ERROR	LDY #FULLERR	BRA ERRHARD	ENTRY ERRSRQERRSRQ	JSR IMD	;PROCESS ANY PING STATUS	LDY #HARDERR	;FLAG ERROR	ENTRY ERRHARDERRHARD	LDX #$0006	;CLEAN 6 BYTES OFF STACK	JMP CALL	;FLAG ERROR ON RETURN** SRQ INTERRUPT HANDLER* This code is entry point for SRQ interrupt handler* If a command is already ping then the	SRQ is ignored* Gets next device in SRQ TABLE and initiates* FDB poll.* Address of next device is stored in SRQTBL.* Get index into SRQTBL by incrementing	SRQPTR. If * of table (SRQNUM)	then set to 0. SRQMRU is used to keep track of* the last device that was active. If all devices in SRQTBL	are polled* and none responded then routine turns	off SRQ on all devices, except* keyboard (2), then reenables SRQ for all devices installed in* SRQ TABLE.** Enter in 8-bit m,x*	ENTRY INTSRQINTSRQ		;       	LONGA OFF	LONGI OFF	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	LONGA ON	LONGI ON	REP #$30	;NEED TO BE IN 16-BIT FOR INIT	JSR INITOOL	;DO INIT STUFF/Returns 'm'=1/'x'=0	LONGA OFF	TCS	;OPENS UP BUFFER INSIDE STACK	LDA |PENDFLAG	;CHECK PING FLAG (DON'T SET)	BMI DONESRQ	;IF SET THEN RETURN*	DEC |SRQCNT	;CHECK IF ALL DEVICES POLLED	BMI OFLIST	;YES	LDA |SRQPTR	;GET POINTER	CMP |SRQNUM	;CHECK IF  OF TABLE	BCC TBL	;NOT YET	LDA #$00	;GOT  - RESET BACK TO BEGINNING	STA |SRQPTR	; (PUT DATA IN A-REG.)*	ENTRY TBLTBL		; 	INC |SRQPTR	;SETUP FOR NEXT DEVICE	ASL A	;A HOLDS CURRENT DEVICE	ASL A	;CALCULATES LOCATION OF FDB ADDRESS IN	XBA	LDA #$00	XBA	TAX	;SRQTBL*	LDY #SRQCPLT	;MOVE LOW WORD OF SRQ COMPLETION	STY |VCTRCPLT+1	;ROUTINE ADDRESS INTO COMPLETION VECTOR	LDA #^SRQCPLT	;GET BANK INTO HI BYTE OF VECTOR	STA |VCTRCPLT+3*	LDA |SRQTBL,X	;GET FDB ADDRESS/REGISTER	ORA #TALKCMD	;MAKE INTO FDB TALK	POLL COMMAND	STA |CMDREG	;S COMMAND	LDA #PENDBIT	;SET COMMAND PING FLAG	TSB |FLAGS	ENTRY DONESRQDONESRQ		; 	REP #$30	;16-BIT M,X	LONGA ON	LONGI ON	JMP CLEAN	;(RETURN FROM INTERRUPT)** This Routine is used if no device in the SRQ list has returned data.* This probably means that some device is generating an SRQ	when it* it shouldn't be. To alleviate this problem, the SRQ of all devices,* except for the keyboard (2), is disabled and then those in the SRQ* list are enabled.*	ENTRY OFLISTOFLIST		; 	LONGA OFF	LDA #$0F	STA |SRQPTR	;USE AS TEMPORARY*	ENTRY ANYMOREANYMORE	LDA |SRQPTR	;GET NEXT DEVICE ADDRESS	CMP #2	;LOOK FOR KEYBOARD ADDRESS	BNE NXTDEV	DEC A	;SKIP KEYBOARD	ENTRY NXTDEVNXTDEV	ORA #DISSRQ	;APP FDB COMMAND TO	FDB ADDRESS	JSR CMDS	;SS COMMAND AND WAIT UNTIL READ	DEC |SRQPTR	;GET NEXT ADDRESS	BPL ANYMORE	;UNTIL NO MORE*	LDA |SRQNUM	;GET NUMBER OF DEVICES IN SRQ TABLE	STA |SRQPTR	ENTRY GETINDGETIND	DEC |SRQPTR	;GET INDEX TO NEXT DEVICE ADDRESS	LDA |SRQPTR	BMI RSTSRQ	;0 = LAST DEVICE	ASL A	;MAKE INDEX INTO SRQ TABLE	ASL A	XBA	LDA #0	XBA	TAY	LDA |SRQTBL,Y	;GET FDB ADDRESS FROM TABLE	AND #$0F	;CLEAR OUT REGISTER	ORA #ENSRQ	;APP FDB COMMAND TO	FDB ADDRESS	JSR CMDS	;SS COMMAND AND WAITS TIL READ	BRA GETIND*	ENTRY RSTSRQRSTSRQ	LDA |SRQMRU	;GET MOST RECENTLY USED DEVICE	STA |SRQPTR	;AND SET POINTER TO	IT	LDA |SRQNUM	;CHECK ALL TABLE ENTRIES AGAIN	STA |SRQCNT	BRA DONESRQ** SRQ COMPLETION ROUTINE* This routine is used to process a response from a FDB poll command* initiated by the SRQ interrupt handler. The SRQ handler is trying* to get data from a device which sent an SRQ to the system.* The response to the poll command was read by the response* interrupt handler	or during another FDB command.* If the response from the command shows no data then* the routine just returns. Later, an SRQ interrupt will enable the* SRQ interrupt handler to initiate a poll of the next device in the* SRQ TABLE.* If the response shows data was returned then this routine	will* update the SRQMRU	(Most Recently Used) with the number of	the* active device. The routine will then* Call the completion vector address for the active device.* A typical completion routine should muck w/ the stack to find* the data. This doesn't because it knows where it is.** Assumes 8-bit m,x	& data stored in direct page locations* Don't clean up before return*	ENTRY SRQCPLTSRQCPLT		; 	LDA <RSPNSBUF	;GET # OF BYTES RECEIVED	BEQ SRQCPL	;IF NO BYTES THEN RETURN*	PHK	;PUSH RETURN ADRS (PROGRAM BANK 1ST)	PER SRQCPL-1	;AFTER COMPLETION VECTOR RETURN->	LDA |SRQNUM	;RESTORE COUNTER - INDICATES # OF	STA |SRQCNT	; DEVICES IN TABLE	LDA |SRQPTR	;SRQPTR POINTS TO NEXT DEVICE	DEC A	;SET TO ACTIVE DEVICE	STA |SRQMRU	;AND SAVE AS MOST RECENTLY USED	ASL A	;GET COMPLETION VECTOR ONTO STACK	ASL A	;ADDRESS STORED IN SRQTBL	TAX	;INDEX INTO SRQTBL	LDA |SRQTBL+3,X	;PUSH PROGRAM BANK # OF ADDRESS ON 1ST	PHA	;PUSH ADDRESS ON STACK THEN RTL	LONGA ON	LONGI ON	REP #$30	;16-BIT MODE	LDA |SRQTBL+1,X	;GET ADDRESS WORD	DEC A	;-1 (USES RTL)	PHA	;PUSH HI BYTE, THEN	LOW BYTE	ENTRY SRQCPLSRQCPL		;Returns here from completion vector	SEP #$30	;Call completion vector routine (8-bit)	LONGA OFF	LONGI OFF	CLC	;2ND THRU RTNS (CLC)->INTRPT DISPATCHER	RTL	;BACK TO SYSTEM INTERRUPT HANDLER** Removes a device from SRQ list* Looks in SRQ table for FDB address passed on stack by calling* routine. If FDB address is in table then removes entry from table,* moves rest of entries up in table.*	ENTRY SRQRMVSRQRMV		;       	LONGA ON	LONGI ON	PHD	PHP	PHB	JSR INITOOL	;Returns 'm'=1/'x'=0	LONGA OFF	TCS	LDA |PENDFLAG	;COMMAND PING SO DON'T ATTEMPT	SEP #$30	LONGI OFF	BMI SKIPRMV	;TO REMOVE DEVICE	LDX |SRQNUM	;START W/ LAST DEVICE IN SRQ TABLE	ENTRY SAMEDEVSAMEDEV	DEX	;GET INDEX FOR DEVICE N =>(N-1)*4	BMI SRQNOTFND	;CAN'T FIND DEVICE IN TABLE	TXA	;BUILD INDEX IN TO TABLE	ASL A	;	ASL A	TAY	LDA |SRQTBL,Y	;GET ADDRESS OF DEVICE IN TABLE	CMP <ZPTOS	;AND SEE IF DEVICE TO BE REMOVED	BNE SAMEDEV	;NOT SAME - GET NEXT DEVICE IN TABLE	REP #$20	LONGA ON	ENTRY FINDDEVFINDDEV	LDA |SRQTBL+6,Y	;FOUND DEVICE	STA |SRQTBL+2,Y	;MOVE NEXT ENTRY IN	TABLE UP ONE	LDA |SRQTBL+4,Y	STA |SRQTBL+0,Y	INY	INY	INY	INY	INX	;SEE IF LAST ENTRY IN TABLE	CPX |SRQNUM	BCC FINDDEV	;NOT LAST ENTRY, MOVE ANOTHER ONE*	DEC |SRQNUM	;LAST ENTRY MOVED -	1 LESS TABLE ENTRY	LDX |SRQNUM	;USE X - 8-BIT	STX |SRQCNT	;RESTORE	STZ |SRQPTR	;ZEROS OUT BOTH SRQPTR AND SRQMRU	LDX #2	JMP NOERR*	ENTRY SKIPRMVSKIPRMV		; 	LDY #BUSYERR	ENTRY SRQSRQ	LDX #2	JMP CALL*	ENTRY SRQNOTFNDSRQNOTFND		; 	LDY #HARDERR	BRA SRQ** Clear out the SRQ	Table of all entries*	ENTRY CLRSRQTBLCLRSRQTBL		;       	LONGA ON	LONGI ON	LDA #$0000	STA >SRQNUM	;ZEROS SRQNUM AND SRQCNT	STA >SRQPTR	;ZEROS SRQPTR AND SRQMRU	CLC	RTL;         copy  ADBTools* uC TOOL SET - SKI	COMMANDS.* ADBTOOLS** S TOOL* This routine is used to implement the	S tool* Since this command is an immediate command it checks if ping* command flag is set. If no ping command it executes immediately.* If command ping then the ping command	must be finished 1st.* READRSPNS gets data from the ping command. The immediate* command is then executed and afterwards the data from the	ping* command is processed by vectoring to the completion routine.*	ENTRY TOOLADBTOOLADB	PROC*USING ADBEQUS*USING E1VECTORS	EXPORT STOOLSTOOL		;       	LONGA ON	LONGI ON	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	JSR INITOOL	;DO INIT STUFF	LONGA OFF	TCS	;OPENS UP BUFFER INSIDE STACK*	JSR SCMD	BCS ERRORCALL	JSR SNDCMDSTR	BCS ERRORCALL*	ENTRY TOOLTOOL	JSR IMD	;CLEAN UP ANY PING STATUS** Clean up stack and finish call**	LDX #$0008	;CLEAN OFF 8 INPUT PARAMETERS	BRA TONOERR	;*	ENTRY ERRORCALLERRORCALL		; 	JSR IMD	;CLEAN UP ANY PING STATUS	LDX #$0008	;CLEAN OFF 8 INPUT PARAMETERS	BRA HARDCALL* RCV TOOL* This routine is used to implement the	RCV tool* Since this command is an immediate command it checks if ping* command flag is set. If no ping command it executes immediately.* If command ping then the ping command	must be finished 1st.* READRSPNS gets data from the ping command. The immediate* command is then executed and afterwards the data from the	ping* command is processed by vectoring to the completion routine.	ENTRY RCVTOOLRCVTOOL		;       	LONGA ON	LONGI ON	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	JSR INITOOL	;DO INIT STUFF	LONGA OFF	TCS	;OPENS UP BUFFER INSIDE STACK*	JSR SCMD	;S IT COMMAND*  ;LEAVES W/DATA REG. CLEAR	BCS ERRORCALL	;ERROR-ABORT THE REST*	LDY #$0000	;SET UP DATA COUNTER	ENTRY ANYDATAANYDATA	CPY <HOWMANY	;SEE IF ANY MORE DATA TO RECEIVE	BCS TOOL	;NO MORE SO GOTO  OF IMMEDIATE TOOL	JSR RCVDATA	;GET DATA	BCS ERRORCALL	;ERROR-ABORT THE REST	STA [<DATAPTR],Y	;SAVE DATA	INY	;GET NEXT BYTE	BRA ANYDATA* RDMEM* Command to read memory location from the uC* Needs both input and output* Command starts by	calling the Command	string	ENTRY RDMEMTOOLRDMEMTOOL		;       	LONGA ON	LONGI ON	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	JSR INITOOL	;DO INIT STUFF	LONGA OFF	TCS	;OPENS UP BUFFER INSIDE STACK*	JSR SCMD	;S COMMAND BYTE	BCS ERRORDMEM	;ERROR-ABORT REST OF COMMAND	LDA [<DATAPTR]	;GET 1ST DATA BYTE (LOW ADDRESS)	JSR SDATA	; AND S IT	BCS ERRORDMEM	;ERROR-ABORT REST OF COMMAND	LDY #$0001	LDA [<DATAPTR],Y	;GET 2ND DATA BYTE (HI ADDRESS)	JSR SDATA	; AND S IT	BCS ERRORDMEM	;ERROR-ABORT REST OF COMMAND	JSR RCVDATA	;READ DATA FROM UC	BCS ERRORDMEM	;ERROR-ABORT REST OF COMMAND	STA [<RDMEMPTR]	;AND STORE IN BUFFER	JSR IMD* Clean up stack and finish call	LDX #$000A	;CLEAN OFF 10 INPUT	PARAMETERS	ENTRY TONOERRTONOERR		; 	JMP NOERR	;*	ENTRY ERRORDMEMERRORDMEM		; 	JSR IMD	;CLEAN UP ANY PING STATUS	LDX #$000A	;CLEAN OFF 10 INPUT	PARAMETERS	ENTRY HARDCALLHARDCALL		; 	LDY #HARDERR	;ERROR CODE	JMP CALL* FDBTALK* Initiates FDB talk command - which is	a ping command* If a command is already ping then flags an error - Busy* Otherwise saves completion vector, sets busy flag and starts command* When sing a ping command, it doesn't wait for the command byte* to be read. The ping flag ensures no overun will occur.* This routine doesn't move the direct page onto the stack, but* instead uses stack relative to get at	the data.	ENTRY FDBTALKFDBTALK		;       	LONGA ON	LONGI ON	PHP	;SAVE INTERRUPT STATUS	LONGA OFF	SEP #$20	;8-BIT M	PHB	;SAVE DATA BANK	LDA #DATABNK	;CHANGE DATA BANKS	PHA	PLB*	LDA $E,S	;GET HI BYTE OF COMPLETION VECTOR	BEQ STRVCTR	;IF=0 THEN STORE COMPLETION VECTOR*	LDY #mytoolnum*256+HARDERR ;OTHERWISE FLAG ERROR	BRA CMDP*	ENTRY STRVCTRSTRVCTR	LDA #PENDBIT	;CHECK COMMAND PING	FLAG ALREADY SET	TSB |FLAGS	;THEN SETS FLAGS	BEQ CMDNP	;COMMAND WASN'T PING*	LDY #mytoolnum*256+BUSYERR ;FLAG CMD ALREADY PING - BUSY	BRA CMDP*	ENTRY CMDNPCMDNP	LDA $B,S	;MOVE VECTOR FROM STACK TO MEMORY	STA |VCTRCPLT+1	LDA $C,S	STA |VCTRCPLT+2	LDA $D,S	STA |VCTRCPLT+3	;PROGRAM BANK	LDA $9,S	;GET COMMAND	STA |CMDREG	;S IT, BUT DON'T WAIT AROUND	LDY #$0000	;NO ERROR;	ENTRY CMDPCMDP		; 	PLB	PLP	;RESTORE STACK	LONGA ON	LDA 5,S	;MOVE RETURN ADDRESS	STA 11,S	; AND GET RID OF INPUT STUFF	LDA 3,S	STA 9,S	LDA 1,S	STA 7,S	PLA	PLA	PLA	TYA	;CHECK ERROR CODE	CMP #$0001	;SET CARRY IF NOT 0	RTL	;RETURN TO GLU* FDB Receive* This command is very similar to the FDB TALK command except* it uses 2 bytes of command instead of	a single	ENTRY FDBRCVFDBRCV		;       	LONGA ON	LONGI ON	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	JSR INITOOL	;DO INIT STUFF	LONGA OFF	TCS	;OPENS UP BUFFER INSIDE STACK** Set up Completion	Vector* Assumes 4-byte address in stack* High byte should be zero - lower 3-bytes hold address* If ping command flag already set then	flag error busy**	LDA <CPLTVCTR+3	;GET HI BYTE OF COMPLETION VECTOR	BNE RET1	;ERROR IF NOT 0*	LDA #PENDBIT	;CHECK PING BIT	TSB |FLAGS	BNE BUSY	;COMMAND ALREADY PING - FLAG BUSY*	LDY <CPLTVCTR	;SAVE OFF LOW WORD OF ADDRESS	STY |VCTRCPLT+1	LDA <CPLTVCTR+2	;SAVE OFF HI BYTE OF ADDRESS	STA |VCTRCPLT+3*	JSR SCMD2	;S COMMAND BYTE	BCS ERROR3	LDA <FDBCMD	;	JSR SDATA	;FOLLOW W/ FDB COMMAND BYTE	BCS ERROR3	JMP TOOL	;CLEAN UP ANY STATUS/RESPONSE LEFTOVERS*  ;RESTORE STACK, ETC.*	ENTRY BUSYBUSY		; 	LDX #$0008	;CLEAN 8 BYTES OF STACK	LDY #BUSYERR	;FLAG BUSY ERROR	JMP CALL*	ENTRY ERROR3ERROR3		; 	LDA #PENDBIT	;SINCE ERROR OCCURRED CLEAR PING FLAG	TRB |FLAGS	JMP ERRORCALL* S command* This routine ss a	command to uC & cleans data reg. for response* If a command is ping then it sets a flag and reads the response* into a buffer, before executing the immediate command. After* performing the immediate command the response is processed.* After sing the immediate command the Status Reg. is read* till either the command is read by the uC (reg. empty) OR	Timeout* The data reg. is then read Immediately to clear out any* ping uC status. This guarantees that the next byte written to the* data reg. will not be status, but data in response to a RCV command.* Valid uC status is stored in Statustmp & processed at  of	command* Should always be followed with an IMD	call to process any	ping* read responses or	status.** 8-bit m, 16-bit x* Error = Carry set	ENTRY SCMDSCMD		;       	LONGA OFF	LONGI ON	JSR CHKDOP	;IF PING FLAG SET THEN READ RESPONSE	BCS RET1	ENTRY SCMD2SCMD2		; ;FOR THE CALL FROM FDBRCV	LDA <UCCMD	;GET COMMAND	ENTRY CMDSCMDS		;       ;COMMON CMDS ENTRY POINT	JSR SDATA	;AND S IT AND WAIT TIL READ	BCS RET1	AND #DATAFULL/2	;CHECK IF DATA REG FULL	BEQ RET1	;NOT FULL	LDA |DATAREG	;FULL - GET uC STATUS	TSB |STATUSTMP	;AND SAVE*	ENTRY RET1RET1	RTS	;CARRY SET = ERR** Routine to read response to if ping flag is set.* Used by immediate	commands to clear out any ping commands*	ENTRY CHKDOPCHKDOP		;       	LONGA OFF	LONGI ON	LDA |PENDFLAG	;CHECK IF COMMAND PING	BPL EXECMD	;NONE - SO EXECUTE IMMEDIATE COMMAND	JSR READRSPNS	;GET PING COMMAND RESPONSE DATA	BCS GETPATA	LDA #RSPNSBIT	TSB |RSPNSFLAG	ENTRY EXECMDEXECMD	CLC	ENTRY GETPATAGETPATA	RTS* S COMMAND STRING* This command ss any bytes after the initial command byte.** Errors = Carry set	ENTRY SNDCMDSTRSNDCMDSTR		; 	LONGA OFF	longi off		SEP #$30	LDA <UCCMD	;GET THE COMMAND FOR ADB	CMP #$06	;IS IT SET CONFIGURATIONS COMMAND?	BNE @1	;BRA IF NOT	LDA |KEYUCVER	;ELSE CHK FOR NEW OR OLD KEYUC	CMP #$06	;>=$06 THEN NEW KEYUC	BCC @1	;BRA FOR OLD ONE	LDY #$02	;INDEX TO DELAY/REPEAT BYTE	LDA [<DATAPTR],Y	;GET IT	PHA	;TEMPORARY SAVE IT	AND #$0F	;MASK OFF FOR REPEAT RATE ONLY	TAX	;AS A NEW INDEX TO NEW TABLE	PLA	AND #$F0	;MAKE REPEAT RATE TO ZERO FIRST	PHA	;SAVE BACK	LDA >NEWTAB,X	;GET THE NEW MAPPING VALUE	ORA 1,S 	;GET BACK THE DELAY VALUE IN HIGH NIBBLES	STA [<DATAPTR],Y	;STORE BACK TO BE READY TO SEND TO KEYUC	PLA	;CLEAN STACK@1	LONGI ON	REP #$10	;8/16 M/X	LDY #$0000	;SET UP DATA COUNTER	ENTRY DATADATA	CPY <HOWMANY	;SEE IF ANY MORE DATA	BCS NOMORE	;NO MORE SO GOTO  OF S TOOL	LDA [<DATAPTR],Y	;OTHERWISE GET DATA	JSR SDATA	BCS ERRORSND	INY	BRA DATA*	ENTRY NOMORENOMORE		; 	CLC	ENTRY ERRORSNDERRORSND	RTSNEWTAB	DC.B $09	;FASTEST REPEAT RATE FOR NEW KEYUC	DC.B $08	DC.B $07	DC.B $06	DC.B $05	DC.B $04	DC.B $03	DC.B $02	DC.B $01	DC.B $00	;LOWEST "* S DATA* S data or command, to the uC using the command reg.* If command reg. is empty ss a data byte, otherwise flags error* If data not read w/ 30 ms. then timeout error* Uses: A (8-BIT)* X (16-BIT)* Input: A=Command* Output: A=KMSTATUS* Errors: CARRY SET	ENTRY SDATASDATA		;       	LONGA OFF	LONGI ON	TAX	;SAVE OFF DATA	LDA |KMSTATUS	;GET CMD REG FULL BIT -> LSB	ROR A	; INTO CARRY	TXA	;GET DATA BACK	BCS ERROUT	;REG. NOT EMPTY SO FLAG ERROR*	STA |CMDREG	;STORE AWAY NEW COMMAND	LDX #7500	;TIMEOUT 7500*(2+2+4+2+3)/3 = 30 MS.	ENTRY REGFULLREGFULL	DEX	;	BEQ FDBTIMEOUT	LDA |KMSTATUS	;GET CMD REG FULL BIT -> LSB	ROR A	; INTO CARRY	BCS REGFULL	;SET IF FULL (NOT READ)*  ;CLR IF EMPTY (READ)*	ENTRY ERROUTERROUT	RTS	;LEAVE W/ A=KMSTATUS CONTENTS** Routine to process the  of a command* Handles any saved	status conditions such as FLUSH, ABORT,	DESKTOP* Handles the response read from a pending	command if it exists* Ignores the Desktop Manager Bit ! This occurs because this code* would have to emulate all the code the interrupt dispatcher* supports before calling the desk manager entry point.** 8-Bit m, 16-bit x	ENTRY IMDIMD		;       	SEP #$30	;8-BIT m,x	LONGA OFF	LONGI OFF	LDA #ABORTBIT+FLUSHBIT ;CLEAR OUT LOW 3	BITS, RESPONSE, SRQ	AND |STATUSTMP	; OF STATUS FLAGS	STA |STATUSTMP	;AND UPDATE STATUS FLAGS	BEQ NOSTSP	;NO pending STATUS CONDITIONS*	CMP #ABORTBIT	;IF ONLY ABORT BIT SET->ABORT CONDITION	BNE NOTSET**  PROCESS ABORT	PHB	;SAVE DATA BANK	LDA #0	;SET DATA BANK =0	PHA	PLB	JSL IRQ_MICRO	;PROCESS ABORT - IF	RETURNS THEN OK	PLB	;RESTORE DATA BANK*	ENTRY NOTSETNOTSET	LDA |STATUSTMP	;LOOK FOR FLUSH BUFFER BIT	ASL A	ASL A	BEQ NOSTSP	;NOT SET	BCC NOTABORT	;IF ABORT BIT SET THEN CLEAR KEYBOARD	STA |KBDSTRB	ENTRY NOTABORTNOTABORT		; 	LDA #0	STA |STATUSTMP	;CLEAR OUT THE REST	OF STATUS BITS	PHB	PHA	;SET DATA BANK TO 0	PLB	JSL IRQ_FLUSH	;PROCESS FLUSH	PLB	;RESTORE DATA BANK*	ENTRY NOSTSPNOSTSP	LDA #RSPNSBIT	TRB |RSPNSFLAG	;TEST & CLEAR OUT RESPONSE FLAG	BEQ NORSPNSE	;IF NO RESPONSE THEN DONE** Response was read, from pending command,	during immediate command* Process data by calling completion vector*	LDA #PENDBIT	TRB |PENDFLAG	;CLEAR COMMAND pending	FLAG	BEQ NORSPNSE*	PEA $0000	;SET UP BUFFER ADDRESS ON STACK	PHD	;BOTTOM OF STACK	LONGA OFF	LONGI OFF	SEP #$30	;8-BIT m,x	JSL VCTRCPLT	;IF RESPONSE READ PREVIOUSLY-PROCESS NOW	LONGA ON	LONGI ON	REP #$30	;16-BIT m,x	PLA	;CLEAN OFF BUFFER ADDRESS	PLA	; IN 16-BIT*	ENTRY NORSPNSENORSPNSE		; 	LONGA OFF	;RESET TO 8-BIT M FROM COMPLETION	LONGI ON	;RESET TO 16-BIT X IF SKIPPED COMPLETION	SEP #$20	;8-BIT M, 16-BIT X	REP #$10	RTS* RECEIVE DATA* Gets data from the data reg.* Assumes the data reg. doesn't contain status (SCMD clears* status from data reg. after command is read)* Uses A,X* 8-bit m, 16-bit x	ENTRY RCVDATARCVDATA		;       	LONGA OFF	LONGI ON	CLC	LDX #7500	;TIMEOUT 7500*(2+2+4+2+3)/3 = 30 MS.	ENTRY REGOKREGOK	DEX	BEQ FDBTIMEOUT	LDA |KMSTATUS	;GET DATA REG FULL BIT -> BIT 5	AND #DATAFULL	;AND TEST	BEQ REGOK	;CLR IF EMPTY (READ)*  ;SET IF FULL (DON'T READ)*	LDA |DATAREG	RTS*	ENTRY FDBTIMEOUTFDBTIMEOUT	SEC	RTS* Reads a response from a FDB pending command* The first response byte has the MSB set (otherwise status) and* indicates in the low 3 bits how many bytes will follow.* This event must be atomic: Can't be interrupted & must be completed* Saves other status bits from response	byte -> STATUSTMP (w/MSB clr)* Saves the response bytes in RSPNSBUF with the first byte indicating* how many bytes are to follow (length). The response bytes	are stored* backwards in the buffer - the first data byte is at the nth* position after the length byte, while	the nth byte received is the* is the first after the length byte (2nd in the buffer). Actually* works out just great since the bytes are transferred from	the uC to* the system in reverse order: last byte received on FDB is	first byte* passed from uC to	the system. This means that the data is	stored* in the buffer in the same order as they are received on FDB from* the device.** ERROR: Carry set	ENTRY READRSPNSREADRSPNS		;       	LONGA OFF	LONGI ON	JSR RCVDATA	;GET DATA BYTE FROM	UC	BCS ERRRSPNS	;TIMEOUT ERROR	BMI GOTRSPNS	;GOT RESPONSE BYTE	TSB |STATUSTMP	;SAVE UC STATUS BYTE	BRA READRSPNS	;GET ANOTHER BYTE*	ENTRY GOTRSPNSGOTRSPNS		; ;GOT RESPONSE BYTE	AND #$7F	;CLEAR OUT RESPONSE	BIT	TSB |STATUSTMP	;SAVE OTHER UC STATUS BITS	ENTRY RSPNSINTRSPNSINT	AND #$07	;GET COUNT FROM LOW	3 BITS	STA <RSPNSBUF	;AND SAVE IN RESPONSE BUFFER	XBA	LDA #0	;CLEAR OUT HI BYTE	XBA	TAY	;COUNT=0 OR N-1 BYTES	BEQ BYTES	;IF 0 THEN NO MORE BYTES TO FOLLOW	INY	;GET COUNT+1 MORE BYTES	ENTRY SOMEMORESOMEMORE	JSR RCVDATA	;GET NEXT BYTE	BCS ERRRSPNS	;TIMEOUT ERROR	TYX	;SETUP X FOR DIRECT	INDEXED	STA <RSPNSBUF,X	;STORE IN BUFFER - START @  &	DEY	; WORK TOWARD BEGINNING OF BUFFER	BNE SOMEMORE	;STORE MORE	ENTRY BYTESBYTES		; ;CARRY CLEAR IF OK	RTS	ENTRY ERRRSPNSERRRSPNS		; ;CARRY SET ON ERROR EXIT	LDA #PENDBIT	;CLEAR OUT pending FLAG ON ERROR	TRB |FLAGS	;IF ERROR ENCOUNTERED	RTS* RESPONSE INTERRUPT HANDLER* This code is the entry point for the response interrupt handler* It reads the response, clears the pending flag, then jumps to* the completion vector.** 8-Bit m, 8-bit x	ENTRY INTRSPNSINTRSPNS		;       	LONGA OFF	LONGI OFF	TAY	;SAVE RESPONSE BYTE-FROM INTRPT DISPATCH	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK	LONGA ON	LONGI ON	REP #$30	;NEED TO BE IN 16-BIT FOR INIT	JSR INITOOL	;DO INIT STUFF	LONGA OFF	TCS	;OPENS UP BUFFER INSIDE STACK	LDA #PENDBIT	;CHECK AND	TRB |FLAGS	;CLEAR OUT pending INTERRUPT*  ;IF NOT SET - ERROR DETECTED ON READ	TYA	;GET BACK RESPONSE BYTE	JSR RSPNSINT	;SAVE RESPONSE BYTE, GET REST -> BUFFER	BCC GOODRSP	;RESPONSE OK*	LDA #0	;FAKE A RESPONSE INSTEAD OF SYSDEATH	STA <RSPNSBUF	;SET # OF BYTES RECEIVED = 0** Routine to call completion vector to process data* Data stored in RSPNSBUF** Completion routine should expect:* 8-bit m,x* Pointer to data stored above return address on stack (4-6,S)* RTLs with stack,m,x intact (don't clean up).*	ENTRY GOODRSPGOODRSP		; ;PUSH ADDRESS OF RESPONSE ONTO STACK	PEA $0000	;HAPPENS TO BE IN BANK 0	PHD	;BOTTOM OF DIRECT PAGE	LONGA ON	LONGI ON	SEP #$30	;GO IN 8-BIT m,x	JSL VCTRCPLT	;COMPLETION VECTOR RETURNS FROM INTERUPT	REP #$30	;GO IN 16-BIT m,x	PLA	;CLEAN OFF STACK FOR COMPLETION ROUTINE	PLA	JMP CLEAN	;USED TO RETURN FROM INTERRUPT*  ;(GOES BACK TO 8-BIT W/ PLP)** INIT sequence for	a typical tool call.* It assumes the following stack structure on entry:** 11-12 Word: Count	of Data bytes (HOWMANY)* D-10 Long: Pointer to Data* B-C Word: Command	to uC* 8-A Adrs: Tool Dispatcher Return* 5-7 Adrs: Calling	Code Return* 3-4 : Original Direct Page* 2 : Processor Status* 1 : Data Bank* TOS->** and adds following:** 2 bytes : Return address from this subroutine* 20 bytes : Buffer	for Response** The direct page is then placed on top	of the stack. The stack is* then pushed down one more byte. This allows the beginning	of the* direct page to be	used as a pointer to data (PHD).* The stack pointer	is not actually moved until the routine	returns* to the tool call.*	ENTRY INITOOLINITOOL		;       	LONGA ON	;START IN 16-BIT MODE	LONGI ON	SEI	;DISABLE INTERRUPTS	TSC	;MAKE ROOM IN STACK	FOR BUFFERS	SEC	; (JSR ALREADY TOOK	2 BYTES)	SBC #RSPNSLNG*2-1	;LEAVE ROOM FOR 2 RESPONSE BUFFERS	TCD	;PUT DIRECT PAGE ONTO FUTURE STACK	DEC A	;ADJUST STACK PTR OUTSIDE ZERO PAGE	JSR DBTOE1	;Changes data bank register to $E1	SEP #$20	;8-BIT ACCUMULATOR	LONGA OFF	RTS	;MOVE TCS AFTER RETURN TO FIX STACK**  Routine* Used to clean up input parameters off	stack,* restore stack pointer, direct page, &	data bank.* Sets up carry for	error.** Input: Y -> Error	code* X=PARMS -> Parameter Bytes on stack to be cleaned off*	ENTRY NOERRNOERR		;       	REP #$30	LONGA ON	LONGI ON	LDY #$0000	;INDICATES NO ERROR	BRA ALL	ENTRY CALLCALL		;       	REP #$30	;RETURN IN 16-BIT m,x	TYA	ORA #MYTOOLNUM*256	;MYTOOL # IN HI BYTE	TAY	ENTRY ALLALL	LDA <RTLGLU+4	;MOVE GLU ROUTINE RETURN ADDRESS	STA <RTLGLU+4,X	LDA <RTLGLU+2	STA <RTLGLU+2,X	; AND CALLING RETURN ADDRESS	LDA <RTLGLU+0	STA <RTLGLU+0,X	STX <PARMS	;SAVE # OF PARAMETERS	TSC	;MOVE STACK POINTER	TO RESTORE STATUS	CLC	ADC #RSPNSLNG*2+2	;POINT TO SAVED STATUS (PLB,P,D)	TCS	ADC <PARMS	;CALCULATE NEW LOCATION OF STACK POINTER	ADC #$0004	;BY ADDING OFFSET +	4 (SAVED STATUS)	TAX	;SAVE FOR NOW	PLB	;RESTORE DATA BANK	PLP	; INTERRUPT STATUS	PLD	; DIRECT PAGE*	TYA	;SET ERROR CODE	CMP #$0001	;SET CARRY FOR ERROR CODE (CLR ON 0)	TXS	;MOVE NEW STACK POINTER	RTL	;RETURN TO GLU* Used to return from an interrupt handler* Enter in 16-bit m,x	ENTRY CLEANCLEAN		;       	LONGA ON	;NEEDED FOR STACK CALCULATION	LONGI ON	TSC	;GET STACK PTR	CLC	ADC #RSPNSLNG*2+2	;POINT TO SAVED STATUS (PLB,P,D)	TCS	;RESTORE STACK POINTER	PLB	;RESTORE DATA BANK	PLP	; STATUS (8-BIT m,x)	PLD	; DIRECT PAGE	CLC	;HANDLED INTERRUPT - NOTIFY DISPATCHER	RTL	;RETURN TO INTERRUPT DISPATCHER** Set data bank to $e1*	ENTRY DBTOE1DBTOE1		;       	PEA $E1E1	PLB	PLB	RTS	ENDP	end